13.获取app缓存大小- (CGFloat)getCachSize &#123;    NSUInteger imageCacheSize = [[SDImageCache sharedImageCache] getSize];    // 获取自定义缓存大小    // 用枚举器遍历 一个文件夹的内容    // 1.获取 文件夹枚举器    NSString *myCachePath = [NSHomeDirectory() stringByAppendingPathComponent:@&quot;Library/Caches&quot;];    NSDirectoryEnumerator *enumerator = [[NSFileManager defaultManager] enumeratorAtPath:myCachePath];    __block NSUInteger count = 0;    // 2.遍历    for (NSString *fileName in enumerator) &#123;        NSString *path = [myCachePath stringByAppendingPathComponent:fileName];        NSDictionary *fileDict = [[NSFileManager defaultManager] attributesOfItemAtPath:path error:nil];        //自定义所有缓存大小        count += fileDict.fileSize;    &#125;    // 得到是字节  转化为M    CGFloat totalSize = ((CGFloat)imageCacheSize+count)/1024/1024;    return totalSize;&#125;

14.清理app缓存- (void)cleanAppCache &#123;    // 删除两部分    // 1.删除 sd 图片缓存    // 先清除内存中的图片缓存    [[SDImageCache sharedImageCache] clearMemory];    // 清除磁盘的缓存    [[SDImageCache sharedImageCache] clearDisk];    // 2.删除自己缓存    NSString *myCachePath = [NSHomeDirectory() stringByAppendingPathComponent:@&quot;Library/Caches&quot;];    [[NSFileManager defaultManager] removeItemAtPath:myCachePath error:nil];&#125;

