/** 计算时长 */- (NSString *)caculateDurationWithStartTime:(NSString *)startTime andEndTime:(NSString *)endTime&#123;    if (endTime == nil) &#123;        return @&quot;未知&quot;;    &#125;    NSDate *startDate 			= [NSDate date];    NSDate *endDate 			= [NSDate date];        NSDateFormatter *format 	= [[NSDateFormatter alloc]init];    format.dateFormat 			= @&quot;YYYY-MM-dd HH:mm:ss&quot;;    format.timeZone				= [NSTimeZone systemTimeZone];    startDate 					= [format dateFromString:startTime];    endDate 						= [format dateFromString:endTime];    NSTimeInterval duration 	= endDate.timeIntervalSince1970 - startDate.timeIntervalSince1970;    int hour 						= (int)duration / 3600;    int min 						= (int)duration % 3600 / 60;    int sec 						= (int)duration % 60;        return [NSString stringWithFormat:@&quot;%d小时%d分%d秒&quot;,hour,min,sec];&#125;

31.计算两个NSDate经历了多少天/** *  返回两个NSDate经历了多少天 */- (NSInteger)getDaysFrom:(NSDate *)startDate To:(NSDate *)endDate&#123;        NSCalendar *gregorian = [[NSCalendar alloc]initWithCalendarIdentifier:NSCalendarIdentifierGregorian];        [gregorian setFirstWeekday:2];        //去掉时分秒信息    NSDate *fromDate;    NSDate *toDate;    [gregorian rangeOfUnit:NSCalendarUnitDay startDate:&amp;fromDate interval:NULL forDate:startDate];    [gregorian rangeOfUnit:NSCalendarUnitDay startDate:&amp;toDate interval:NULL forDate:endDate];    NSDateComponents *dayComponents = [gregorian components:NSCalendarUnitDay fromDate:fromDate toDate:toDate options:0];        return dayComponents.day;&#125;

