4.插入排序⒈ 从第一个元素开始，该元素可以认为已经被排序⒉ 取出下一个元素，在已经排序的元素序列中从后向前扫描⒊ 如果该元素（已排序）大于新元素，将该元素移到下一位置⒋ 重复步骤3，直到找到已排序的元素小于或者等于新元素的位置⒌ 将新元素插入到下一位置中⒍ 重复步骤2~5
public func insertionSort(arr: inout Array&lt;Int&gt;) &#123;    for i in 0..&lt;arr.count - 1 &#123;        if arr[i + 1] &lt; arr[i] &#123;            let temp = arr[i + 1]            for j in (1...(i + 1)).reversed() &#123;                if arr[j - 1] &gt; temp &#123;                    (arr[j - 1],arr[j]) = (arr[j],arr[j - 1])                &#125;            &#125;        &#125;    &#125;&#125;

5.冒泡排序⒈比较相邻的元素。如果第一个比第二个大，就交换他们两个。⒉ 对每一对相邻元素作同样的工作，从开始第一对到结尾的最后一对。在这一点，最后的元素应该会是最大的数。⒊ 针对所有的元素重复以上的步骤，除了最后一个。⒋ 持续每次对越来越少的元素重复上面的步骤，直到没有任何一对数字需要比较。
public func bubbleSort(arr: inout Array&lt;Int&gt;) &#123;    for i in 0..&lt;(arr.count - 1) &#123;        for j in 0..&lt;(arr.count - i - 1) &#123;            if arr[j] &gt; arr[j + 1] &#123;                (arr[j],arr[j + 1]) = (arr[j + 1],arr[j])            &#125;        &#125;    &#125;&#125;

6.快速排序（冒泡排序的改进版）⒈设置两个变量i、j，排序开始的时候：i&#x3D;0，j&#x3D;n-1。⒉ 以第一个数组元素作为关键数据，赋值给key，即key&#x3D;A[0]。⒊ 从j开始向前搜索，即由后开始向前搜索(j–)，找到第一个小于key的值A[j]，将A[j]和A[i]互换。⒋ 从i开始向后搜索，即由前开始向后搜索(i++)，找到第一个大于key的A[i]，将A[i]和A[j]互换。⒌重复第3、4步，直到i&#x3D;j
 public func quickSort(arr: inout Array&lt;Int&gt;, leftIndex:  Int, rightIndex:  Int) &#123;    if leftIndex &lt; rightIndex &#123;        var left = leftIndex        var right = rightIndex        let midIndex = getMidIndex(arr: &amp;mArray, leftIndex: &amp;left, rightIndex: &amp;right)        quickSort(arr: &amp;mArray, leftIndex: leftIndex, rightIndex: midIndex - 1)        quickSort(arr: &amp;mArray, leftIndex: midIndex + 1, rightIndex: rightIndex)    &#125;&#125;private func getMidIndex(arr: inout Array&lt;Int&gt;, leftIndex: inout Int, rightIndex: inout Int) -&gt; (Int) &#123;    let temp = arr[leftIndex]    while leftIndex &lt; rightIndex &#123;        while leftIndex &lt; rightIndex &amp;&amp; temp &lt;= arr[rightIndex] &#123;            rightIndex -= 1        &#125;        if leftIndex &lt; rightIndex &#123;            arr[leftIndex] = arr[rightIndex]        &#125;        while leftIndex &lt; rightIndex &amp;&amp; arr[leftIndex] &lt;= temp &#123;            leftIndex += 1        &#125;        if leftIndex &lt; rightIndex &#123;            arr[rightIndex] = arr[leftIndex]        &#125;    &#125;    arr[leftIndex] = temp    return leftIndex&#125;
7.归并排序（速度仅次于快速排序）⒈将序列每相邻两个数字进行归并操作（merge)，形成floor(n&#x2F;2)个序列，排序后每个序列包含两个元素。⒉ 将上述序列再次归并，形成floor(n&#x2F;4)个序列，每个序列包含四个元素。⒊ 重复步骤2，直到所有元素排序完毕。
 public func mergeSort(arr: inout Array&lt;Int&gt;) &#123;    var tempArr: Array&lt;Array&lt;Int&gt;&gt; = []    for item in arr &#123;       var subArr: Array&lt;Int&gt; = []       subArr.append(item)       tempArr.append(subArr)    &#125;    while tempArr.count != 1 &#123;        var i = 0        while i &lt; tempArr.count - 1 &#123;            tempArr[i] = mergeTowArr(arr1: tempArr[i], arr2: tempArr[i+1])            tempArr.remove(at : i+1)            i += 1        &#125;    &#125; &#125;private func mergeTowArr(arr1: Array&lt;Int&gt;, arr2: Array&lt;Int&gt;) -&gt; Array&lt;Int&gt; &#123;    var mergeArr: Array&lt;Int&gt; = []    var firstIndex = 0    var secondIndex = 0    while firstIndex &lt; arr1.count &amp;&amp; secondIndex &lt; arr2.count &#123;        if arr1[firstIndex]  &lt; arr2[secondIndex] &#123;            merge.append(arr1[firstIndex])            firstIndex += 1        &#125;else&#123;            merge.append(arr2[secondIndex])            secondIndex += 1        &#125;    &#125;    while firstIndex &lt; arr1.count &#123;         merge.append(arr1[firstIndex])         firstIndex += 1    &#125;    while secondIndex &lt; arr2.count &#123;         merge.append(arr2[secondIndex])         secondIndex += 1    &#125;    return mergeArr&#125;

8.选择排序选择排序（Selection sort）是一种简单直观的排序算法。它的工作原理是每一次从待排序的数据元素中选出最小（或最大）的一个元素，存放在序列的起始位置，直到全部待排序的数据元素排完。 选择排序是不稳定的排序方法（比如序列[5， 5， 3]第一次就将第一个[5]与[3]交换，导致第一个5挪动到第二个5后面）
public func selectSort(arr: inout Array&lt;Int&gt;) &#123;    for i in 0..&lt;arr.count &#123;        var index = i        for j in (i + 1)..&lt;arr.count &#123;            if arr[index] &gt; arr[j] &#123;                index = j            &#125;        &#125;        if index != i &#123;            (arr[i],arr[index]) = (arr[index],arr[i])        &#125;    &#125;&#125;
9.堆排序（选择排序的一种）通过headMakeFrom将数组arr变为大顶堆，再把大顶堆的第一值和最后一个值交换，数组长度减1。通过heapAdjast将交换后的数组重新排序成大顶堆直到数组长度为0。
public func heapSort(arr: inout Array&lt;Int&gt;) &#123;//时间复杂度O(n*logn)    var endIndex = arr.count - 1    headMakeFrom(arr: &amp;arr)    while endIndex &gt; 0 &#123;        (arr[0],arr[endIndex]) = (arr[endIndex],arr[0])        heapAdjast(arr: &amp;arr,starIndex: 1, arrLength: endIndex)        endIndex -= 1    &#125;&#125;private func heapMakeFrom(arr: inout Array&lt;Int&gt;) &#123;    var lastHead = arr.count/2    while lastHead &gt; 0 &#123;        heapAdjast(arr:  &amp;arr, starIndex: lastHead, arrLenght: arr.count)        lastHead -= 1    &#125;&#125;private func heapAdjast(arr: Array&lt;Int&gt;, starIndex: Int, arrLength: Int) &#123;    var temp = arr[starIndex - 1]    var parentIndex = starIndex    var childIndex = 2 * parentIndex    while childIndex &lt;= arrLength &#123;        if childIndex &lt; arrLength &amp;&amp; arr[childIndex] &gt; arr[childIndex - 1] &#123;            childIndex += 1        &#125;        if arr[childIndex-1] &gt; temp &#123;            arr[parentIndex - 1] = arr[childIndex - 1]        &#125;else&#123;            break         &#125;        parentIndex = childIndex        childIndex = 2 * parentIndex     &#125;    arr[parentIndex - 1] = temp&#125;
